using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Preserve EF8 discriminator property name (EF9 changed default to "$type")
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");
        // Preserve EF8 compound id format "Blog|1" (EF9 uses key-only by default)
        modelBuilder.Entity<Blog>().HasRootDiscriminatorInJsonId(true);
        // HasIndex removed: Cosmos DB throws at startup in EF9. Manage indexing
        // via the container's indexing policy (Azure Portal / Bicep / Terraform).
    }
}

